// German B1 practice rooms: 6 modules x 12 rooms x 3 questions.
window.deRooms = window.deRooms || {};
deRooms.B1 = [
  // Module 1: Expressing Opinions
  [
    {t:"Opinion phrases",s:"Vocabulary",qs:[
      {q:"What does 'Meiner Meinung nach' mean?",opts:["In my opinion","In my experience","To my surprise","In my absence"],a:0,ex:"'Die Meinung' means opinion; 'meiner Meinung nach' is a fixed phrase that introduces your own view."},
      {q:"Which phrase means 'I agree with that'?",opts:["Da stimme ich zu","Das sehe ich anders","Da bin ich dagegen","Das stimmt nicht"],a:0,ex:"'zustimmen' means to agree; 'da' points back to what the other person just said."},
      {q:"What does the verb 'überzeugen' mean?",opts:["to convince","to translate","to overtake","to surprise"],a:0,ex:"'überzeugen' (to convince) is related to 'die Überzeugung', a firm belief or conviction."}]},
    {t:"Agreeing and disagreeing",s:"Vocabulary",qs:[
      {q:"Which phrase expresses disagreement politely?",opts:["Das sehe ich anders","Da hast du recht","Genau so ist es","Da stimme ich zu"],a:0,ex:"'Das sehe ich anders' (I see that differently) disagrees without attacking the other person."},
      {q:"Complete: 'Einerseits ist das Auto praktisch, ___ ist es schlecht für die Umwelt.'",opts:["andererseits","außerdem","zuerst","deshalb"],a:0,ex:"'einerseits' is balanced by 'andererseits' to present two opposite sides of an issue."},
      {q:"'Ich bin der Ansicht, dass ...' is closest in meaning to …",opts:["Ich bin der Meinung, dass ...","Ich bin sehr müde, weil ...","Ich habe keine Ahnung, ob ...","Ich sehe mir an, wie ..."],a:0,ex:"'Die Ansicht' means view; 'der Ansicht sein' and 'der Meinung sein' both mean to hold an opinion."}]},
    {t:"Sounds in opinion words",s:"Pronunciation",qs:[
      {q:"Listen. Which part of 'überzeugen' is stressed?",say:"überzeugen",opts:["-zeu-","ü-","-ber-","-gen"],a:0,ex:"The inseparable prefix über- in 'überzeugen' is unstressed, so the stress falls on the verb stem -zeu-."},
      {q:"Listen. How is the 'ei' in 'Meinung' pronounced?",say:"Meinung",opts:["like 'eye' in English","like 'ay' in 'day'","like 'ee' in 'see'","like 'oy' in 'boy'"],a:0,ex:"German 'ei' is always pronounced like English 'eye'; 'ie' is the one that sounds like 'ee'."},
      {q:"Listen. How is the 'ch' in 'Ansicht' pronounced?",say:"Ansicht",opts:["the soft ich-sound","the throaty ach-sound","like 'ch' in 'church'","like 'k' in 'kite'"],a:0,ex:"After front vowels like i, 'ch' is the soft ich-sound; the throaty ach-sound comes after a, o, u and au."}]},
    {t:"dass and weil: verb last",s:"Grammar",qs:[
      {q:"Which sentence with 'dass' is correct?",opts:["Ich finde, dass er recht hat.","Ich finde, dass er hat recht.","Ich finde, dass hat er recht.","Ich finde, er dass recht hat."],a:0,ex:"'dass' starts a subordinate clause, so the conjugated verb 'hat' moves to the very end."},
      {q:"Complete: 'Ich glaube, dass das Essen hier zu teuer ___.'",opts:["ist","sein","bist","sind"],a:0,ex:"After 'dass' the verb goes last and agrees with the subject 'das Essen' (third person singular)."},
      {q:"Complete: 'Ich bleibe zu Hause, ___ es draußen zu kalt ist.'",opts:["weil","denn","deshalb","aber"],a:0,ex:"Only 'weil' sends the verb to the end; 'denn' and 'aber' keep normal order and 'deshalb' inverts."}]},
    {t:"Opinions: tricky word order",s:"Grammar",qs:[
      {q:"Which word order is correct after 'Meiner Meinung nach'?",opts:["Meiner Meinung nach ist das wichtig.","Meiner Meinung nach das ist wichtig.","Meiner Meinung nach das wichtig ist.","Meiner Meinung nach wichtig das ist."],a:0,ex:"'Meiner Meinung nach' fills position 1, so the verb comes next in position 2, then the subject."},
      {q:"Which dass-clause with a modal verb is correct?",opts:["Ich finde, dass wir mehr üben sollten.","Ich finde, dass wir sollten mehr üben.","Ich finde, dass wir mehr sollten üben.","Ich finde, dass sollten wir mehr üben."],a:0,ex:"In a dass-clause the conjugated modal 'sollten' stands after the infinitive, at the very end."},
      {q:"Complete: 'Ich bin anderer Meinung, weil man mit dem Fahrrad schneller ___.'",opts:["ankommt","kommt an","an kommt","ankommen"],a:0,ex:"In a weil-clause a separable verb rejoins its prefix at the end and is written as one word."}]},
    {t:"Reading: forum opinions",s:"Reading",qs:[
      {q:"Read: 'Ich finde, dass Handys in der Schule verboten sein sollten. Die Schüler lernen besser, wenn sie nicht abgelenkt sind.' What is the writer's opinion?",opts:["Phones should be banned at school.","Phones help pupils learn better.","Schools should buy more phones.","Pupils need phones for homework."],a:0,ex:"'verboten sein sollten' means 'should be forbidden', and the reason given is fewer distractions."},
      {q:"Read: 'Meiner Meinung nach ist Homeoffice super. Ich spare jeden Tag eine Stunde, weil ich nicht zur Arbeit fahren muss.' Why does the writer like it?",opts:["He saves an hour of commuting.","He earns more money at home.","He likes his colleagues more.","He has a bigger desk at home."],a:0,ex:"The weil-clause gives the reason: he doesn't have to travel to work, which saves an hour a day."},
      {q:"Read: 'Viele sagen, dass Bio-Essen zu teuer ist. Das sehe ich anders: Wer weniger Fleisch kauft, kann sich gutes Gemüse leisten.' What does the writer think?",opts:["Organic food can be affordable.","Organic food is too expensive.","People should eat more meat.","Vegetables are always cheap."],a:0,ex:"'Das sehe ich anders' rejects the view that organic food is too expensive, and the writer explains how to afford it."}]},
    {t:"Listening: who agrees?",s:"Listening",qs:[
      {q:"Listen. Does the speaker agree or disagree?",say:"Da stimme ich dir völlig zu.",opts:["Agrees completely","Disagrees completely","Is not sure yet","Changes the topic"],a:0,ex:"'zustimmen' means to agree and 'völlig' means completely."},
      {q:"Listen. Why is the speaker against the plan?",say:"Ich bin dagegen, weil es viel zu teuer ist.",opts:["It is far too expensive.","It takes far too long.","It is too dangerous.","It is too far away."],a:0,ex:"'dagegen sein' means to be against something; the weil-clause gives the reason: 'zu teuer'."},
      {q:"Listen. What does the speaker think about the film?",say:"Meiner Meinung nach war der Film zu lang, aber die Musik war toll.",opts:["Too long, but great music","Short, with boring music","Too long, with boring music","Perfect in every way"],a:0,ex:"'zu lang' means too long, and 'aber die Musik war toll' adds a positive point about the music."}]},
    {t:"Discussing politely",s:"Speaking",qs:[
      {q:"A colleague says: 'Wir sollten das Meeting verschieben.' You disagree politely. What do you say?",opts:["Das sehe ich ein bisschen anders.","Das ist totaler Quatsch.","Genau, das finde ich auch.","Mir ist das völlig egal."],a:0,ex:"'Das sehe ich ein bisschen anders' disagrees in a soft, polite way; 'Quatsch' (nonsense) is rude."},
      {q:"Your friend says cities should ban cars. You only partly agree. What fits best?",opts:["Da stimme ich dir teilweise zu.","Da hast du völlig recht.","Das sehe ich ganz anders.","Dazu habe ich keine Meinung."],a:0,ex:"'teilweise' means partly, so 'Da stimme ich dir teilweise zu' expresses partial agreement."},
      {q:"Someone asks: 'Was meinst du dazu?' Which answer gives an opinion with a reason?",opts:["Ich finde es gut, weil es Zeit spart.","Ich weiß, dass heute Montag ist.","Ich habe das gestern gemacht.","Ich frage morgen meinen Bruder."],a:0,ex:"'Ich finde es gut' is an opinion and the weil-clause adds the reason: it saves time."}]},
    {t:"Writing an opinion post",s:"Writing",qs:[
      {q:"Choose the correctly written opinion sentence.",opts:["Ich bin der Ansicht, dass Sport wichtig ist.","Ich bin der Ansicht dass Sport wichtig ist.","Ich bin der Ansicht, dass Sport ist wichtig.","Ich bin die Ansicht, dass Sport wichtig ist."],a:0,ex:"A comma must come before 'dass', the verb goes last, and the fixed phrase is 'der Ansicht sein' (genitive)."},
      {q:"Complete the post correctly: 'Ich komme heute nicht, ___'",opts:["weil ich keine Zeit habe.","weil ich habe keine Zeit.","weil habe ich keine Zeit.","weil keine Zeit ich habe."],a:0,ex:"In a weil-clause the subject follows 'weil' and the conjugated verb 'habe' goes to the end."},
      {q:"Fill the gap: 'Ich finde Radfahren toll. ___ ist es gesund, und zweitens spart man Geld.'",opts:["Erstens","Trotzdem","Dagegen","Obwohl"],a:0,ex:"'Erstens ... zweitens' (firstly ... secondly) lists arguments; 'obwohl' would need the verb at the end."}]},
    {t:"German discussion culture",s:"Culture",qs:[
      {q:"In a German work meeting, how is disagreement usually expressed?",opts:["Quite directly, with factual reasons","Never; people always stay silent","Only in writing after the meeting","By changing the subject quickly"],a:0,ex:"German discussion culture values directness: open, fact-based disagreement is seen as honest, not rude."},
      {q:"Which opinion phrase sounds most formal, e.g. in an essay?",opts:["Ich bin der Ansicht, dass ...","Ich find das echt cool.","Na ja, ich mein halt ...","Krass, oder was?"],a:0,ex:"'der Ansicht sein' belongs to formal, written German; the other phrases are casual spoken language."},
      {q:"In a discussion with your manager, how do you politely interrupt?",opts:["Darf ich kurz etwas dazu sagen?","Halt mal, jetzt rede ich!","Hör mal endlich zu!","Moment, du liegst falsch!"],a:0,ex:"Asking permission with 'Darf ich kurz ...?' is the polite way to join in; the others sound aggressive."}]},
    {t:"Opinions recap",s:"Review",qs:[
      {q:"Which of these words sends the verb to the end of the clause?",opts:["dass","denn","aber","und"],a:0,ex:"'dass' is a subordinating conjunction; 'denn', 'aber' and 'und' are coordinating and keep normal order."},
      {q:"What is the opposite of 'Da stimme ich zu'?",opts:["Da bin ich anderer Meinung.","Da hast du recht.","Das finde ich auch.","Genau so sehe ich das."],a:0,ex:"'anderer Meinung sein' means to have a different opinion, i.e. to disagree."},
      {q:"Complete: 'Deine Argumente sind gut – du hast mich ___.'",opts:["überzeugt","überzeugen","überzeugte","überzeugst"],a:0,ex:"The perfect tense needs a past participle; inseparable verbs like 'überzeugen' take no ge-: 'überzeugt'."}]},
    {t:"Challenge: opinions",s:"Challenge",qs:[
      {q:"Which sentence with two subordinate clauses is correct?",opts:["Ich finde, dass er recht hat, weil er viel Erfahrung hat.","Ich finde, dass er hat recht, weil er viel Erfahrung hat.","Ich finde, dass er recht hat, weil er hat viel Erfahrung.","Ich finde, dass hat er recht, weil er viel Erfahrung hat."],a:0,ex:"Both 'dass' and 'weil' are subordinating, so 'hat' must stand at the end of each clause."},
      {q:"Which sentence starting with 'Weil' has the correct word order?",opts:["Weil es regnet, finde ich den Ausflug keine gute Idee.","Weil es regnet, ich finde den Ausflug keine gute Idee.","Weil regnet es, finde ich den Ausflug keine gute Idee.","Weil es regnet, den Ausflug finde ich keine gute Idee."],a:0,ex:"The whole weil-clause is position 1, so the main clause must start with its verb: 'finde ich'."},
      {q:"Complete: 'Viele meinen, Homeoffice ist produktiv. ___, denn zu Hause wird man oft abgelenkt.'",opts:["Das sehe ich anders","Da stimme ich zu","Das finde ich auch","Genau richtig"],a:0,ex:"The reason 'zu Hause wird man abgelenkt' argues against the claim, so only a disagreement phrase fits."}]}
  ],
  // Module 2: Subordinate Clauses
  [
    {t:"Connector words",s:"Vocabulary",qs:[
      {q:"What does 'obwohl' mean?",opts:["although","because","so that","whether"],a:0,ex:"'obwohl' introduces a contrast: something happens in spite of something else."},
      {q:"What does 'damit' mean when it joins two clauses?",opts:["so that","although","after","unless"],a:0,ex:"As a conjunction 'damit' expresses purpose: 'Ich spare, damit ich reisen kann.'"},
      {q:"Which word means 'whether'?",opts:["ob","ab","wenn","als"],a:0,ex:"'ob' introduces indirect yes/no questions: 'Ich weiß nicht, ob er kommt.'"}]},
    {t:"bevor, nachdem, trotzdem",s:"Vocabulary",qs:[
      {q:"Which word is the opposite of 'bevor'?",opts:["nachdem","obwohl","damit","sobald"],a:0,ex:"'bevor' means before and 'nachdem' means after; both send the verb to the end."},
      {q:"What does 'trotzdem' mean?",opts:["nevertheless","therefore","meanwhile","otherwise"],a:0,ex:"'trotzdem' comes from 'trotz' (despite): something happens in spite of what was said before."},
      {q:"Which word means 'when' for a single event in the past?",opts:["als","wenn","wann","ob"],a:0,ex:"'als' is for one past event or period; 'wenn' is for repeated or future events; 'wann' asks a question."}]},
    {t:"Stress in connectors",s:"Pronunciation",qs:[
      {q:"Listen. Where is the stress in 'obwohl'?",say:"obwohl",opts:["on the second syllable","on the first syllable","on both syllables equally","on neither syllable"],a:0,ex:"'obwohl' is stressed on -wohl; the 'oh' is a long vowel, lengthened by the silent h."},
      {q:"Listen. How is the 'ch' in 'nachdem' pronounced?",say:"nachdem",opts:["the throaty ach-sound","the soft ich-sound","like a hard 'k'","like 'sh' in 'ship'"],a:0,ex:"After a back vowel like 'a', 'ch' is the throaty ach-sound made at the back of the mouth."},
      {q:"Listen. What does the 'w' in 'wenn' sound like?",say:"wenn",opts:["like English 'v'","like English 'w'","like English 'f'","it is silent"],a:0,ex:"German 'w' is always pronounced like English 'v': wenn, wohl, warum."}]},
    {t:"Verb to the end",s:"Grammar",qs:[
      {q:"Complete: 'Wir gehen spazieren, obwohl es ___.'",opts:["regnet","regnen","geregnet","regnet es"],a:0,ex:"'obwohl' sends the conjugated verb to the end, and with 'es' it must be 'regnet'."},
      {q:"Which sentence with 'ob' is correct?",opts:["Ich weiß nicht, ob er heute kommt.","Ich weiß nicht, ob kommt er heute.","Ich weiß nicht, ob er kommt heute.","Ich weiß nicht ob, er heute kommt."],a:0,ex:"The comma goes before 'ob', and the verb 'kommt' moves to the end of the ob-clause."},
      {q:"Complete: 'Ich lerne Deutsch, ___ ich in Berlin arbeiten kann.'",opts:["damit","trotzdem","ob","als"],a:0,ex:"'damit' expresses purpose (so that) and sends the modal 'kann' to the end."}]},
    {t:"Clause first; wenn vs als",s:"Grammar",qs:[
      {q:"Which sentence starting with 'Obwohl' is correct?",opts:["Obwohl es regnet, gehen wir spazieren.","Obwohl es regnet, wir gehen spazieren.","Obwohl regnet es, gehen wir spazieren.","Obwohl es regnet, gehen spazieren wir."],a:0,ex:"When the subordinate clause comes first, the main clause starts with its verb: verb, comma, verb."},
      {q:"Complete: '___ ich klein war, wohnte ich in Bonn.'",opts:["Als","Wenn","Wann","Ob"],a:0,ex:"Childhood is one period in the past, so German uses 'als', not 'wenn'."},
      {q:"Complete: '___ ich nach Hamburg fahre, besuche ich immer meine Tante.'",opts:["Wenn","Als","Wann","Ob"],a:0,ex:"'immer' shows a repeated event, which needs 'wenn' (whenever), not 'als'."}]},
    {t:"Reading: a learner's story",s:"Reading",qs:[
      {q:"Read: 'Als ich 15 war, habe ich mit Deutsch angefangen. Obwohl die Grammatik schwer war, hat es mir Spaß gemacht.' How did the writer feel?",opts:["Enjoyed it despite hard grammar","Gave up because of the grammar","Found the grammar very easy","Started learning it at age 50"],a:0,ex:"'Obwohl ... schwer war' shows the grammar was hard, but 'hat mir Spaß gemacht' means it was fun."},
      {q:"Read: 'Bevor ich nach Wien gezogen bin, habe ich einen Sprachkurs gemacht. Nachdem ich angekommen war, habe ich Arbeit gefunden.' What happened first?",opts:["The language course","Finding a job","Moving to Vienna","Arriving in Vienna"],a:0,ex:"'Bevor ich gezogen bin' means the course came before the move; the job came after arriving."},
      {q:"Read: 'Ich weiß noch nicht, ob ich morgen komme. Wenn ich Zeit habe, rufe ich dich an.' What does the writer promise?",opts:["To call if there is time","To come tomorrow for sure","Never to call again","To come without calling"],a:0,ex:"'Wenn ich Zeit habe, rufe ich dich an' is a condition: the call depends on having time."}]},
    {t:"Listening: why and when",s:"Listening",qs:[
      {q:"Listen. Why can't the speaker come?",say:"Ich kann leider nicht kommen, weil ich arbeiten muss.",opts:["He has to work.","He is ill.","He has no car.","He is on holiday."],a:0,ex:"The weil-clause gives the reason: 'ich arbeiten muss' means he has to work."},
      {q:"Listen. When did the speaker live in Munich?",say:"Als ich Student war, habe ich in München gewohnt.",opts:["When he was a student","When he was a child","After he retired","Since last year"],a:0,ex:"'Als ich Student war' refers to the single past period when he was a student."},
      {q:"Listen. What does the speaker do despite the weather?",say:"Obwohl es kalt ist, gehe ich joggen.",opts:["He goes jogging.","He stays at home.","He goes swimming.","He takes the bus."],a:0,ex:"'Obwohl es kalt ist' means although it is cold; the main clause says he goes jogging."}]},
    {t:"Giving reasons in talk",s:"Speaking",qs:[
      {q:"Your friend asks: 'Warum lernst du Deutsch?' Which answer is correct?",opts:["Weil ich in Deutschland studieren möchte.","Weil ich möchte in Deutschland studieren.","Weil möchte ich in Deutschland studieren.","Denn ich in Deutschland studieren möchte."],a:0,ex:"A short answer with 'weil' still needs verb-final order: 'möchte' goes to the end."},
      {q:"Someone asks: 'Kommst du morgen mit ins Kino?' You're unsure. What do you say?",opts:["Ich weiß noch nicht, ob ich Zeit habe.","Ich weiß noch nicht, dass ich Zeit habe.","Ich weiß noch nicht, wenn ich Zeit habe.","Ich weiß noch nicht, als ich Zeit habe."],a:0,ex:"An open yes/no question after 'Ich weiß nicht' needs 'ob'; 'dass' would state a known fact."},
      {q:"You want to say you will call after you have eaten. What fits?",opts:["Ich rufe dich an, nachdem ich gegessen habe.","Ich rufe dich an, bevor ich gegessen habe.","Ich rufe dich an, obwohl ich gegessen habe.","Ich rufe dich an, ob ich gegessen habe."],a:0,ex:"'nachdem' (after) places the call after eating; 'bevor' means before and 'obwohl' means although."}]},
    {t:"Writing: commas and joins",s:"Writing",qs:[
      {q:"Choose the correctly punctuated sentence.",opts:["Wenn du Zeit hast, komm doch vorbei.","Wenn du Zeit hast komm doch vorbei.","Wenn du Zeit, hast komm doch vorbei.","Wenn, du Zeit hast komm doch vorbei."],a:0,ex:"A comma always separates the subordinate clause from the main clause, right after its verb."},
      {q:"Join with 'trotzdem': 'Ich war müde. Ich habe weitergearbeitet.'",opts:["Ich war müde, trotzdem habe ich weitergearbeitet.","Ich war müde, trotzdem ich habe weitergearbeitet.","Ich war müde, trotzdem ich weitergearbeitet habe.","Ich war müde, habe trotzdem ich weitergearbeitet."],a:0,ex:"'trotzdem' is an adverb, not a conjunction: it takes position 1, so the verb follows directly."},
      {q:"Fill the gap in the email: 'Liebe Anna, ich schreibe dir, ___ du weißt, wann ich ankomme.'",opts:["damit","trotzdem","als","nachdem"],a:0,ex:"The writer's purpose is that Anna knows the arrival time, so 'damit' (so that) fits."}]},
    {t:"Commas and spoken weil",s:"Culture",qs:[
      {q:"In written German, are commas before subordinate clauses optional?",opts:["No, they are always required.","Yes, they are always optional.","Only in private letters.","Only after 'obwohl'."],a:0,ex:"German punctuation rules require a comma between main and subordinate clauses, unlike English."},
      {q:"Many Germans say 'weil ich hab keine Zeit' with main-clause order. How is this viewed?",opts:["Common in speech, wrong in writing","Correct in all formal texts","Used only in Austria","Required in B1 exams"],a:0,ex:"'weil' with verb-second order is widespread in casual speech, but standard written German needs the verb last."},
      {q:"Which connector meaning 'since/as' sounds more formal than 'weil'?",opts:["da","halt","na ja","echt"],a:0,ex:"'da' (since, as) also sends the verb to the end and is typical of formal and written German."}]},
    {t:"Connectors recap",s:"Review",qs:[
      {q:"Which word is NOT a subordinating conjunction?",opts:["trotzdem","obwohl","nachdem","bevor"],a:0,ex:"'trotzdem' is an adverb, so the verb follows it directly; the others send the verb to the end."},
      {q:"Complete: 'Ich frage mich, ___ das wirklich stimmt.'",opts:["ob","wenn","als","dass"],a:0,ex:"'sich fragen' introduces an open yes/no question, which needs 'ob'."},
      {q:"Complete: 'Sie spart jeden Monat Geld, ___ sie im Sommer reisen kann.'",opts:["damit","trotzdem","deshalb","ob"],a:0,ex:"The verb 'kann' is at the end, so a subordinating conjunction is needed; 'damit' shows the purpose."}]},
    {t:"Challenge: complex sentences",s:"Challenge",qs:[
      {q:"Which dass-clause with a modal in the past is correct?",opts:["Ich weiß, dass er gestern nicht kommen konnte.","Ich weiß, dass er gestern nicht konnte kommen.","Ich weiß, dass er konnte gestern nicht kommen.","Ich weiß, dass konnte er gestern nicht kommen."],a:0,ex:"In a subordinate clause the conjugated modal 'konnte' comes last, after the infinitive 'kommen'."},
      {q:"Which sentence about yesterday evening is correct?",opts:["Als ich gestern nach Hause kam, war niemand da.","Wenn ich gestern nach Hause kam, war niemand da.","Als ich gestern nach Hause kam, niemand war da.","Als ich gestern kam nach Hause, war niemand da."],a:0,ex:"A single past event needs 'als', the verb goes last in that clause, and the main clause starts with 'war'."},
      {q:"Complete the relative clause: 'Das Buch, ___ ich gerade lese, ist spannend.'",opts:["das","den","der","dem"],a:0,ex:"'Buch' is neuter and is the object of 'lese', so the relative pronoun is accusative neuter: 'das'."}]}
  ],
  // Module 3: Work, Media & Reported Ideas
  [
    {t:"Job words",s:"Vocabulary",qs:[
      {q:"What is 'die Bewerbung'?",opts:["the job application","the job interview","the promotion","the salary"],a:0,ex:"'sich bewerben' means to apply, so 'die Bewerbung' is the application; the interview is 'das Vorstellungsgespräch'."},
      {q:"What does 'der Arbeitgeber' mean?",opts:["the employer","the employee","the colleague","the trainee"],a:0,ex:"'Arbeit geben' means to give work, so the Arbeitgeber is the employer; the employee is 'der Arbeitnehmer'."},
      {q:"Which word means 'the salary'?",opts:["das Gehalt","der Lebenslauf","die Besprechung","die Sendung"],a:0,ex:"'das Gehalt' is a monthly salary; 'der Lebenslauf' is a CV and 'die Besprechung' a meeting."}]},
    {t:"Media and CV words",s:"Vocabulary",qs:[
      {q:"On TV, what are 'die Nachrichten'?",opts:["the news","the adverts","the quiz shows","the weather report"],a:0,ex:"'die Nachrichten' are the news; the singular 'die Nachricht' can also mean a message."},
      {q:"What is 'der Lebenslauf'?",opts:["the CV / résumé","the cover letter","the work contract","the reference letter"],a:0,ex:"'der Lebenslauf' literally means 'course of life': a list of your education and jobs."},
      {q:"Complete: '___ Wetterbericht wird es morgen regnen.'",opts:["Laut","Wegen","Seit","Über"],a:0,ex:"'laut' means according to and introduces a source, often without an article: 'laut Wetterbericht'."}]},
    {t:"Workplace words aloud",s:"Pronunciation",qs:[
      {q:"Listen. Which part of 'Bewerbung' is stressed?",say:"Bewerbung",opts:["the middle: -wer-","the start: Be-","the end: -bung","all parts equally"],a:0,ex:"The prefix be- is never stressed in German, so the stress falls on the stem -wer-."},
      {q:"Listen. How is the ending '-ung' in 'Besprechung' pronounced?",say:"Besprechung",opts:["like 'ung' in 'lung'","with a hard 'g' as in 'go'","with a 'k' sound at the end","like 'unj' with a soft j"],a:0,ex:"In '-ung' the letters ng form one sound, as in English 'sing'; no separate g is heard."},
      {q:"Listen. The 'h' in 'Gehalt' is …",say:"Gehalt",opts:["pronounced as a breathy h","silent, as in 'gehen'","pronounced like 'ch'","pronounced like 'k'"],a:0,ex:"An h at the start of a syllable (Ge-halt) is spoken; it is only silent after a vowel, as in 'gehen'."}]},
    {t:"deshalb, sei and wird",s:"Grammar",qs:[
      {q:"Complete: 'Ich bin krank, deshalb ___ zu Hause.'",opts:["bleibe ich","ich bleibe","bleiben ich","ich bleiben"],a:0,ex:"'deshalb' takes position 1 of its clause, so the verb comes next and the subject follows."},
      {q:"'Ich bin müde', sagt er. Reported: 'Er sagt, er ___ müde.'",opts:["sei","sein","seid","seien"],a:0,ex:"The Konjunktiv I of 'sein' for er/sie/es is 'sei'; it marks reported speech in news and formal texts."},
      {q:"Passive: 'Man stellt das Produkt in Deutschland her.' → 'Das Produkt ___ in Deutschland hergestellt.'",opts:["wird","hat","werden","wirst"],a:0,ex:"The present passive is werden + past participle, and the singular subject 'das Produkt' needs 'wird'."}]},
    {t:"Reporting and passive",s:"Grammar",qs:[
      {q:"'Ich habe keine Zeit', sagt sie. Which report uses Konjunktiv I correctly?",opts:["Sie sagt, sie habe keine Zeit.","Sie sagt, sie haben keine Zeit.","Sie sagt, sie hätten keine Zeit.","Sie sagt, sie habest keine Zeit."],a:0,ex:"Konjunktiv I of 'haben' for sie (she) is 'habe', which differs from the indicative 'hat'."},
      {q:"Which sentence with 'deswegen' is correct?",opts:["Der Zug hatte Verspätung, deswegen kam ich zu spät.","Der Zug hatte Verspätung, deswegen ich kam zu spät.","Der Zug hatte Verspätung, deswegen ich zu spät kam.","Der Zug hatte Verspätung, kam deswegen zu spät ich."],a:0,ex:"Like 'deshalb', 'deswegen' is an adverb in position 1, so the verb 'kam' follows directly."},
      {q:"Complete the news sentence: 'Die neue Brücke ___ nächstes Jahr gebaut.'",opts:["wird","werden","ist","hat"],a:0,ex:"A process in the passive uses 'werden'; with the singular 'die Brücke' the form is 'wird'."}]},
    {t:"Reading: ads and news",s:"Reading",qs:[
      {q:"Read the ad: 'Wir suchen eine Bürokraft in Teilzeit. Bitte schicken Sie Ihre Bewerbung mit Lebenslauf bis 30. Mai.' What must applicants send?",opts:["An application with a CV","Only a photo of themselves","A reference from a teacher","An Excel certificate"],a:0,ex:"'Bewerbung mit Lebenslauf' means an application together with a CV, due by 30 May."},
      {q:"Read the news: 'Laut Polizei wurde gestern in der Innenstadt ein Auto gestohlen. Zeugen werden gebeten, sich zu melden.' What are witnesses asked to do?",opts:["Contact the police","Buy a new car","Avoid the city centre","Lock their cars"],a:0,ex:"'sich melden' means to get in touch; witnesses (Zeugen) are asked to report to the police."},
      {q:"Read: 'Frau Klein sagt, sie sei mit ihrem Gehalt zufrieden, aber die Besprechungen dauerten zu lange.' What is she unhappy about?",opts:["The long meetings","Her salary","Her colleagues","Her office"],a:0,ex:"She is 'zufrieden' (satisfied) with her salary, but says the meetings (Besprechungen) last too long."}]},
    {t:"Listening: news and reports",s:"Listening",qs:[
      {q:"Listen. What is the news report about?",say:"In Hamburg wird ab Montag ein neuer Bahnhof gebaut.",opts:["A new station in Hamburg","A strike in Hamburg","A new airport in Berlin","Train delays on Monday"],a:0,ex:"'wird gebaut' is passive: a new station (Bahnhof) is being built in Hamburg from Monday."},
      {q:"Listen. What did Tom say?",say:"Tom sagt, er habe eine neue Stelle gefunden.",opts:["He has found a new job.","He has lost his job.","He is looking for a flat.","He wants a pay rise."],a:0,ex:"'die Stelle' means a job or position; 'er habe gefunden' reports what Tom said."},
      {q:"Listen. Why is the speaker staying late at the office?",say:"Morgen ist eine wichtige Besprechung, deshalb bleibe ich heute länger.",opts:["An important meeting tomorrow","His boss asked him to stay","He started work late today","His computer was broken"],a:0,ex:"The first clause gives the cause (an important meeting), and 'deshalb' introduces the consequence."}]},
    {t:"Talking about work",s:"Speaking",qs:[
      {q:"In an interview you're asked: 'Warum möchten Sie bei uns arbeiten?' Which answer fits best?",opts:["Ihre Firma ist innovativ und passt zu mir.","Ich habe keine Ahnung, ehrlich gesagt.","Weil ich gerade nichts Besseres habe.","Meine Mutter hat es mir empfohlen."],a:0,ex:"A good answer links the company's qualities to yourself; the others sound unmotivated."},
      {q:"A colleague missed the meeting. How do you report what the boss said?",opts:["Die Chefin hat gesagt, dass das Projekt verschoben wird.","Die Chefin hat gesagt, dass das Projekt wird verschoben.","Die Chefin hat gesagt, das Projekt verschoben wird.","Die Chefin hat gesagt, dass wird das Projekt verschoben."],a:0,ex:"After 'dass' the conjugated verb 'wird' goes to the very end, after the participle 'verschoben'."},
      {q:"A new acquaintance asks: 'Was machen Sie beruflich?' What is a good answer?",opts:["Ich bin Krankenpfleger in einer Klinik.","Ich spiele gern Fußball im Verein.","Ich gehe heute Abend ins Kino.","Mir geht es beruflich sehr gut."],a:0,ex:"'beruflich' asks about your job, so you name your profession and workplace."}]},
    {t:"Writing: letters and summaries",s:"Writing",qs:[
      {q:"Choose the correct first sentence for a cover letter.",opts:["Hiermit bewerbe ich mich um die Stelle.","Hiermit bewerbe ich um die Stelle.","Hiermit ich bewerbe mich um die Stelle.","Hiermit bewerbe mich ich um die Stelle."],a:0,ex:"'sich bewerben' is reflexive and needs 'mich'; after 'Hiermit' the verb comes second."},
      {q:"Fill the gap in a news summary: 'Laut ___ Regierung steigen die Preise.'",opts:["der","die","den","das"],a:0,ex:"'laut' takes the dative (or genitive), and 'die Regierung' becomes 'der Regierung' in both cases."},
      {q:"Which sentence correctly reports a minister's statement?",opts:["Der Minister sagte, die Lage sei stabil.","Der Minister sagte, die Lage seien stabil.","Der Minister sagte, die Lage sein stabil.","Der Minister sagte, die Lage seist stabil."],a:0,ex:"'die Lage' is singular, so the Konjunktiv I of 'sein' is 'sei'."}]},
    {t:"German work and media",s:"Culture",qs:[
      {q:"What does a typical German job application (Bewerbung) include?",opts:["Cover letter, CV and references","Only a one-line email","A personality test result","Your bank statements"],a:0,ex:"A German Bewerbung usually contains an Anschreiben, a Lebenslauf and Zeugnisse (certificates and references)."},
      {q:"How do colleagues in traditional German offices first address each other?",opts:["With 'Sie' and the surname","With 'du' and nicknames","Only with job titles","With 'Hey' and first names"],a:0,ex:"Traditional workplaces start with 'Sie + Herr/Frau + surname'; many start-ups now use 'du' from day one."},
      {q:"What is 'die Tagesschau'?",opts:["a famous TV news programme","a daily newspaper","a radio quiz show","a weather app"],a:0,ex:"'Die Tagesschau' (ARD) first aired in 1952, is Germany's best-known TV news show, famous for its 8 pm edition."}]},
    {t:"Work and media recap",s:"Review",qs:[
      {q:"What does 'die Sendung' mean on TV or radio?",opts:["the broadcast / programme","the channel","the presenter","the remote control"],a:0,ex:"'senden' means to broadcast, so 'die Sendung' is a programme; the channel is 'der Sender'."},
      {q:"After which connector does the verb come immediately (position 2)?",opts:["daher","weil","dass","obwohl"],a:0,ex:"'daher' is an adverb like 'deshalb' and is followed by the verb; the others send the verb to the end."},
      {q:"'Er sagt, dass er kommt.' Which version uses Konjunktiv I without 'dass'?",opts:["Er sagt, er komme.","Er sagt, er kommen.","Er sagt, komme er.","Er sagt, er gekommen."],a:0,ex:"Without 'dass', reported speech keeps main-clause order, and 'komme' is the Konjunktiv I form for er."}]},
    {t:"Challenge: reports",s:"Challenge",qs:[
      {q:"'Wir haben keine Zeit', sagen die Kollegen. Which report is correct in formal German?",opts:["Die Kollegen sagen, sie hätten keine Zeit.","Die Kollegen sagen, sie habe keine Zeit.","Die Kollegen sagen, sie hat keine Zeit.","Die Kollegen sagen, sie hättest keine Zeit."],a:0,ex:"Plural Konjunktiv I 'sie haben' looks like the indicative, so Konjunktiv II 'hätten' replaces it."},
      {q:"Which passive sentence in the past tense is correct?",opts:["Das Gesetz wurde gestern beschlossen.","Das Gesetz wird gestern beschlossen.","Das Gesetz wurde gestern beschließen.","Das Gesetz hat gestern beschlossen."],a:0,ex:"The past passive is 'wurde' + past participle; 'gestern' rules out the present 'wird'."},
      {q:"Complete: 'Die Firma hat viele Aufträge, ___ sucht sie neue Mitarbeiter.'",opts:["daher","weil","obwohl","denn"],a:0,ex:"The verb 'sucht' follows the gap directly, so only an adverb of consequence like 'daher' fits."}]}
  ],
  // Module 4: Advice, Plans & Problem Solving
  [
    {t:"Advice words",s:"Vocabulary",qs:[
      {q:"What does 'Du solltest ...' mean?",opts:["You should ...","You must ...","You wanted ...","You may ..."],a:0,ex:"'solltest' is the Konjunktiv II of 'sollen' and gives friendly advice, weaker than 'musst'."},
      {q:"What is 'die Lösung'?",opts:["the solution","the problem","the question","the delay"],a:0,ex:"'die Lösung' comes from 'lösen' (to solve), so it means the solution."},
      {q:"'Wie wäre es mit ...?' means …",opts:["How about ...?","What is it with ...?","Where would it be ...?","How was it with ...?"],a:0,ex:"'Wie wäre es mit ...?' is a polite suggestion, e.g. 'Wie wäre es mit einem Kaffee?'"}]},
    {t:"Plans and intentions",s:"Vocabulary",qs:[
      {q:"Which phrase means 'If I were you, I would ...'?",opts:["An deiner Stelle würde ich ...","An meiner Stelle würdest du ...","Bei dir wäre ich gern ...","Statt dir würde ich ..."],a:0,ex:"'die Stelle' here means place: 'an deiner Stelle' = in your place, followed by 'würde ich'."},
      {q:"What does 'Ich habe vor, ... zu ...' express?",opts:["an intention","a complaint","a memory","an apology"],a:0,ex:"'vorhaben' means to intend or plan: 'Ich habe vor, nach Wien zu ziehen.'"},
      {q:"Which verb belongs to the noun 'die Lösung'?",opts:["lösen","lesen","lassen","löschen"],a:0,ex:"Many -ung nouns come from verbs: lösen (to solve) → die Lösung (the solution)."}]},
    {t:"würde, wäre and vor-",s:"Pronunciation",qs:[
      {q:"Listen. Which vowel do you hear in 'würde'?",say:"würde",opts:["ü, with rounded lips","u, as in 'gut'","i, as in 'wir'","ö, as in 'schön'"],a:0,ex:"'ü' is said like 'i' but with rounded lips; it distinguishes 'würde' (would) from 'wurde' (became)."},
      {q:"Listen. Which word do you hear in the suggestion?",say:"Wie wäre es mit Pizza?",opts:["wäre","war","wahr","wer"],a:0,ex:"'wäre' has a long ä sound and two syllables; it is the Konjunktiv II of 'sein'."},
      {q:"Listen. Which part of 'vorhaben' is stressed?",say:"vorhaben",opts:["the prefix vor-","the stem -ha-","the ending -ben","all parts equally"],a:0,ex:"Separable prefixes like vor- always carry the stress: VORhaben, ANrufen, AUFstehen."}]},
    {t:"sollte and werden",s:"Grammar",qs:[
      {q:"Complete: 'Du ___ mehr schlafen.'",opts:["solltest","sollte","solltet","sollten"],a:0,ex:"With 'du' the Konjunktiv II of 'sollen' ends in -st: 'du solltest'."},
      {q:"Complete: 'Nächstes Jahr ___ ich nach Wien ziehen.'",opts:["werde","wird","wirst","werden"],a:0,ex:"Futur I is werden + infinitive, and with 'ich' the form is 'werde'."},
      {q:"Which advice sentence has the correct word order?",opts:["Ihr solltet früher losfahren.","Ihr solltet losfahren früher.","Ihr losfahren solltet früher.","Ihr früher solltet losfahren."],a:0,ex:"The modal 'solltet' is in position 2 and the infinitive 'losfahren' goes to the end."}]},
    {t:"vorhaben, würde, zu",s:"Grammar",qs:[
      {q:"Complete: 'Ich habe vor, im Sommer Spanisch ___.'",opts:["zu lernen","lernen","zu gelernt","lerne"],a:0,ex:"'vorhaben' is followed by an infinitive clause with 'zu' + infinitive at the end."},
      {q:"Complete: 'An deiner Stelle ___ ich mit dem Chef sprechen.'",opts:["würde","werde","wurde","wäre"],a:0,ex:"Hypothetical advice uses Konjunktiv II: 'würde' + infinitive; 'wurde' is simple past."},
      {q:"Complete: 'Ich habe vor, morgen früh ___.'",opts:["aufzustehen","zu aufstehen","aufstehen zu","aufzustanden"],a:0,ex:"With separable verbs 'zu' goes between prefix and stem and is written as one word: 'aufzustehen'."}]},
    {t:"Reading: advice column",s:"Reading",qs:[
      {q:"Read: 'Mein Nachbar ist jede Nacht laut. Was soll ich tun? – Tim' Reply: 'Lieber Tim, Sie sollten zuerst freundlich mit ihm sprechen.' What is Tim's first step?",opts:["Talk to the neighbour kindly","Call the police at once","Move to a new flat","Write to the landlord"],a:0,ex:"'zuerst' means first, and 'freundlich mit ihm sprechen' means to talk to him in a friendly way."},
      {q:"Read: 'Ich habe vor, nächstes Jahr ein Semester in Graz zu studieren. Deshalb werde ich jetzt Geld sparen.' Why will the writer save money?",opts:["To study in Graz","To buy a car in Graz","To visit family next year","To pay for a language app"],a:0,ex:"The plan ('Ich habe vor ...') is a semester in Graz, and 'deshalb' links the saving to that plan."},
      {q:"Read: 'Wie wäre es mit einem Picknick am Samstag? Falls es regnet, könnten wir ins Museum gehen.' What is the plan B?",opts:["Going to the museum","Having a picnic","Staying at home","Going on Sunday"],a:0,ex:"'Falls es regnet' (if it rains) introduces the alternative: going to the museum."}]},
    {t:"Listening: tips and plans",s:"Listening",qs:[
      {q:"Listen. What advice does the speaker give?",say:"Du solltest mehr Wasser trinken.",opts:["Drink more water.","Eat more fruit.","Sleep for longer.","Do more sport."],a:0,ex:"'Du solltest' gives advice, and 'mehr Wasser trinken' means to drink more water."},
      {q:"Listen. What is the speaker planning?",say:"Im Herbst werde ich einen Tanzkurs machen.",opts:["A dance course in autumn","A cooking class in spring","A trip in the summer","A new job in winter"],a:0,ex:"'Im Herbst' means in autumn, and 'werde ... machen' is Futur I for a plan."},
      {q:"Listen. What does the speaker suggest?",say:"Wir könnten heute Abend zusammen kochen.",opts:["Cooking together tonight","Eating out tonight","Cooking alone tomorrow","Shopping together today"],a:0,ex:"'Wir könnten' makes a polite suggestion, and 'zusammen kochen' means to cook together."}]},
    {t:"Giving advice in talk",s:"Speaking",qs:[
      {q:"Your friend has lost his passport abroad. What is the best advice?",opts:["Du solltest den Verlust der Polizei melden.","Du solltest sofort in den Urlaub fahren.","Du solltest den Pass einfach vergessen.","Du solltest heute Abend Pizza essen."],a:0,ex:"Reporting the loss (Verlust) to the police is the sensible first step; 'melden' means to report."},
      {q:"A colleague says: 'Ich bin total gestresst.' What is a polite suggestion?",opts:["Wie wäre es mit einer kurzen Pause?","Wie war es mit einer kurzen Pause?","Wo wäre es mit einer kurzen Pause?","Was wäre es mit einer kurzen Pause?"],a:0,ex:"The fixed suggestion phrase is 'Wie wäre es mit ...?'; 'war' is past and does not suggest anything."},
      {q:"Someone asks: 'Was hast du am Wochenende vor?' Which answer fits?",opts:["Ich habe vor, meine Oma zu besuchen.","Ich habe meine Oma vor besucht.","Ich hatte vor, meine Oma besuchen.","Ich habe vor, meine Oma besuchen zu."],a:0,ex:"'vorhaben' takes 'zu' + infinitive at the end of the clause: '... meine Oma zu besuchen'."}]},
    {t:"Writing a future plan",s:"Writing",qs:[
      {q:"Choose the correctly written sentence for your five-year plan.",opts:["In fünf Jahren werde ich ein eigenes Café haben.","In fünf Jahren ich werde ein eigenes Café haben.","In fünf Jahren werde ich ein eigenes Café hätte.","In fünf Jahren werde haben ich ein eigenes Café."],a:0,ex:"The time phrase is position 1, 'werde' comes second, and the infinitive 'haben' goes last."},
      {q:"Fill the gap: 'Du hast Ärger mit deinem Vermieter? Ich ___ dir raten, einen Brief zu schreiben.'",opts:["würde","wäre","wurde","hätte"],a:0,ex:"'Ich würde dir raten' (I would advise you) is a polite Konjunktiv II way to give advice."},
      {q:"Which sentence about solving the problem has the correct word order?",opts:["Morgen werde ich das Problem lösen.","Morgen ich werde das Problem lösen.","Morgen werde ich lösen das Problem.","Morgen werde das Problem ich lösen."],a:0,ex:"After 'Morgen' the verb 'werde' comes second, then the subject, and the infinitive goes last."}]},
    {t:"Polite advice culture",s:"Culture",qs:[
      {q:"Why is 'Sie sollten ...' often preferred over 'Sie müssen ...' when advising?",opts:["It sounds softer and more polite.","It is the only correct form.","It means the advice is a law.","It is used only with children."],a:0,ex:"'müssen' sounds like an obligation, while 'sollten' gives a recommendation and leaves the choice open."},
      {q:"In Germany, where can tenants get advice about a problem with their landlord?",opts:["Mieterverein (tenants' association)","Finanzamt (tax office)","Standesamt (registry office)","Fundbüro (lost and found)"],a:0,ex:"A Mieterverein advises its members on rent, repairs and disputes with landlords."},
      {q:"What is a common German way to soften a suggestion?",opts:["Adding 'vielleicht' or 'doch'","Speaking much more loudly","Using a bare command only","Adding 'sofort' at the end"],a:0,ex:"Small words like 'vielleicht' (perhaps) or 'doch' (Komm doch mit!) make suggestions friendlier."}]},
    {t:"Advice and plans recap",s:"Review",qs:[
      {q:"Which form is the Konjunktiv II of 'sollen' for 'ich'?",opts:["sollte","soll","sollst","gesollt"],a:0,ex:"Konjunktiv II of 'sollen' is 'sollte'; it looks like the past but is used for advice."},
      {q:"What does 'Ich werde ...' + infinitive express?",opts:["the future","the past","a wish","a command"],a:0,ex:"werden + infinitive forms Futur I: 'Ich werde morgen anrufen' = I will call tomorrow."},
      {q:"Complete: 'Wir ___ morgen ins Kino gehen, wenn du Lust hast.'",opts:["könnten","konnten","können zu","gekonnt"],a:0,ex:"'könnten' (Konjunktiv II) makes a polite suggestion; 'konnten' is simple past."}]},
    {t:"Challenge: advice and plans",s:"Challenge",qs:[
      {q:"Which sentence correctly says what you would have done?",opts:["Ich hätte an deiner Stelle früher angerufen.","Ich würde an deiner Stelle früher angerufen.","Ich hätte an deiner Stelle früher anrufen.","Ich wäre an deiner Stelle früher angerufen."],a:0,ex:"Past Konjunktiv II is 'hätte/wäre' + participle; 'anrufen' takes 'haben', so 'hätte ... angerufen'."},
      {q:"Turn 'Du solltest weniger arbeiten' into a past regret.",opts:["Du hättest weniger arbeiten sollen.","Du solltest weniger gearbeitet.","Du hattest weniger arbeiten sollen.","Du sollst weniger arbeiten haben."],a:0,ex:"Past advice uses 'hätte' + infinitive + modal infinitive: 'hättest ... arbeiten sollen'."},
      {q:"Complete: 'Er hat vor, sich nächste Woche bei der Firma ___.'",opts:["zu bewerben","bewerben zu","zu beworben","bewirbt zu"],a:0,ex:"'vorhaben' needs 'zu' + infinitive at the end; the reflexive 'sich' stays near the start of the clause."}]}
  ],
  // Module 5: Essays, Interviews & Review
  [
    {t:"Essay and interview words",s:"Vocabulary",qs:[
      {q:"What does 'Zusammenfassend' mean?",opts:["In summary","For example","In contrast","At first"],a:0,ex:"'zusammenfassen' means to summarise, so 'Zusammenfassend' opens a conclusion."},
      {q:"What is 'die Stärke' in a job interview?",opts:["the strength","the weakness","the experience","the salary"],a:0,ex:"'stark' means strong, so 'die Stärke' is a strength; the opposite is 'die Schwäche'."},
      {q:"Which word means 'In addition'?",opts:["Außerdem","Zunächst","Trotzdem","Abschließend"],a:0,ex:"'Außerdem' adds a further argument; 'Zunächst' means firstly and 'Abschließend' finally."}]},
    {t:"Strengths and connectors",s:"Vocabulary",qs:[
      {q:"What is the opposite of 'die Stärke'?",opts:["die Schwäche","die Erfahrung","die Leistung","die Aufgabe"],a:0,ex:"'schwach' (weak) is the opposite of 'stark' (strong), so 'die Schwäche' is a weakness."},
      {q:"Complete: 'Ich habe viel Erfahrung ___ Kunden.'",opts:["mit","an","für","über"],a:0,ex:"The fixed phrase is 'Erfahrung haben mit' + dative: experience with something."},
      {q:"Which word introduces the first argument of an essay?",opts:["Zunächst","Zusammenfassend","Abschließend","Außerdem"],a:0,ex:"'Zunächst' means firstly; 'Zusammenfassend' and 'Abschließend' belong at the end."}]},
    {t:"Sch-, -fah- and z",s:"Pronunciation",qs:[
      {q:"Listen. How does 'Schwäche' begin?",say:"Schwäche",opts:["'sh' + 'v', as in 'shv'","'sk' + 'w', as in 'square'","'s' + 'w', as in 'sweet'","'ch' + 'w', as in 'church'"],a:0,ex:"'sch' is like English 'sh' and German 'w' sounds like 'v', so 'Schw-' sounds like 'shv'."},
      {q:"Listen. Which part of 'Erfahrung' is stressed?",say:"Erfahrung",opts:["the middle: -fah-","the start: Er-","the end: -rung","all parts equally"],a:0,ex:"The prefix er- is unstressed, so the stress falls on the stem -fah-, with a long a."},
      {q:"Listen. How is the 'z' in 'Zusammenfassend' pronounced?",say:"Zusammenfassend",opts:["like 'ts'","like English 'z'","like 's'","like 'tsch'"],a:0,ex:"German 'z' is always pronounced 'ts', as in 'Zeit', 'Zug' and 'zusammen'."}]},
    {t:"Essay connectors",s:"Grammar",qs:[
      {q:"Complete: 'Einerseits ist es teuer, andererseits ___ sehr nützlich.'",opts:["ist es","es ist","sein es","es sein"],a:0,ex:"'andererseits' takes position 1, so the verb comes next: 'andererseits ist es'."},
      {q:"Complete: 'Zusammenfassend lässt sich sagen, ___ Homeoffice Vor- und Nachteile hat.'",opts:["dass","das","ob","weil"],a:0,ex:"The conjunction 'dass' (with ss) introduces the content clause; 'das' is an article or pronoun."},
      {q:"Which sentence with 'Außerdem' is correct?",opts:["Außerdem spart man viel Zeit.","Außerdem man spart viel Zeit.","Außerdem man viel Zeit spart.","Außerdem viel Zeit man spart."],a:0,ex:"'Außerdem' is an adverb in position 1, so the verb 'spart' must come second."}]},
    {t:"sich bewerben and conclusions",s:"Grammar",qs:[
      {q:"Complete: 'Ich bewerbe ___ um die Stelle als Projektleiter.'",opts:["mich","mir","sich","dich"],a:0,ex:"'sich bewerben' is reflexive, and with 'ich' the accusative reflexive pronoun is 'mich'."},
      {q:"Complete: 'Sie hat ___ um ein Stipendium beworben.'",opts:["sich","sie","ihr","ihm"],a:0,ex:"In the third person the reflexive pronoun is always 'sich', not 'sie' or 'ihr'."},
      {q:"Which conclusion sentence with 'Abschließend' is correct?",opts:["Abschließend möchte ich betonen, dass Teamarbeit wichtig ist.","Abschließend ich möchte betonen, dass Teamarbeit wichtig ist.","Abschließend möchte ich betonen, dass Teamarbeit ist wichtig.","Abschließend möchte betonen ich, dass Teamarbeit wichtig ist."],a:0,ex:"The verb comes second after 'Abschließend', and in the dass-clause 'ist' goes to the end."}]},
    {t:"Reading: essay and interview",s:"Reading",qs:[
      {q:"Read the essay intro: 'Immer mehr Menschen arbeiten im Homeoffice. Im Folgenden werden die Vor- und Nachteile diskutiert.' What will the essay do?",opts:["Discuss pros and cons","Give only advantages","Tell a personal story","Describe an office building"],a:0,ex:"'Vor- und Nachteile' are advantages and disadvantages, and 'im Folgenden' means in what follows."},
      {q:"Read: 'Einerseits spart man Fahrzeit, andererseits fehlt der Kontakt zu den Kollegen.' Which disadvantage is mentioned?",opts:["Less contact with colleagues","Longer travel time","A lower salary","Too many meetings"],a:0,ex:"'fehlt der Kontakt' means the contact is missing; saving travel time is the advantage."},
      {q:"Read: 'Meine größte Stärke ist meine Geduld. Eine Schwäche ist, dass ich manchmal zu perfektionistisch bin.' What is the candidate's weakness?",opts:["Being too perfectionist","Being impatient","Working too slowly","Lacking experience"],a:0,ex:"'Geduld' (patience) is the strength; the weakness is being 'zu perfektionistisch'."}]},
    {t:"Listening: interview answers",s:"Listening",qs:[
      {q:"Listen. What is the candidate's strength?",say:"Meine Stärke ist Teamarbeit.",opts:["Teamwork","Punctuality","Languages","Creativity"],a:0,ex:"'Teamarbeit' means teamwork; 'meine Stärke ist' introduces the strength."},
      {q:"Listen. What experience does the speaker have?",say:"Ich habe drei Jahre Erfahrung im Verkauf.",opts:["Three years in sales","Three months in sales","Three years in teaching","Two years in marketing"],a:0,ex:"'drei Jahre' means three years and 'der Verkauf' means sales."},
      {q:"Listen. Which part of an essay is this sentence from?",say:"Abschließend möchte ich sagen, dass beide Seiten Vorteile haben.",opts:["the conclusion","the introduction","the first argument","the title"],a:0,ex:"'Abschließend' (finally, to conclude) is a typical opener for the Schluss of an essay."}]},
    {t:"Job interview answers",s:"Speaking",qs:[
      {q:"The interviewer asks: 'Was motiviert Sie?' Which answer fits?",opts:["Mich motiviert, Neues zu lernen.","Ich motiviere Sie sehr gern.","Mich motiviert um acht Uhr.","Sie motivieren mich nicht."],a:0,ex:"'Mich motiviert ...' names what motivates you; here it is learning new things."},
      {q:"The interviewer asks: 'Was sind Ihre Schwächen?' What is a good, honest answer?",opts:["Ich bin manchmal ungeduldig, arbeite aber daran.","Ich habe überhaupt keine Schwächen.","Das geht Sie wirklich nichts an.","Meine Schwäche ist Schokolade."],a:0,ex:"A good answer names a real weakness and shows you are working on it."},
      {q:"At the end of an interview, which question is good to ask?",opts:["Wie sieht ein typischer Arbeitstag aus?","Wie viel Urlaub haben Sie gemacht?","Wann darf ich heute wieder gehen?","Warum ist Ihr Büro so klein?"],a:0,ex:"Asking about a typical working day shows interest in the job; the others are irrelevant or rude."}]},
    {t:"Writing: essay structure",s:"Writing",qs:[
      {q:"What is the correct order of the parts of an essay?",opts:["Einleitung – Hauptteil – Schluss","Schluss – Einleitung – Hauptteil","Hauptteil – Schluss – Einleitung","Einleitung – Schluss – Hauptteil"],a:0,ex:"An essay starts with an introduction (Einleitung), then the body (Hauptteil), then a conclusion (Schluss)."},
      {q:"Fill the gap: '___ ist Homeoffice flexibel. Außerdem spart man Geld.'",opts:["Zunächst","Zusammenfassend","Abschließend","Trotzdem"],a:0,ex:"The first argument is followed by 'Außerdem', so the gap needs an opener like 'Zunächst' (firstly)."},
      {q:"Choose the correctly written sentence for a cover letter.",opts:["Ich habe Erfahrung mit Social Media und arbeite gern im Team.","Ich habe Erfahrung mit Social Media und gern arbeite im Team.","Ich habe Erfahrung mit Social Media und arbeiten gern im Team.","Ich habe Erfahrung mit Social Media und im Team gern arbeite."],a:0,ex:"After 'und' the second main clause keeps the verb second, and 'arbeite' must agree with 'ich'."}]},
    {t:"Interviews and CVs in Germany",s:"Culture",qs:[
      {q:"How is a German CV (Lebenslauf) usually organised?",opts:["In reverse chronological order","As a story about your childhood","By your hobbies and sports","By your parents' professions"],a:0,ex:"A German Lebenslauf is a clear table, usually listing the most recent job or education first."},
      {q:"Which essay opener sounds right in formal written German?",opts:["Heute wird oft diskutiert, ob ...","Also, ich sag mal so, dass ...","Hey Leute, heute geht's um ...","Na ja, irgendwie ist es so ..."],a:0,ex:"A formal essay opens neutrally, often with a passive; 'Hey Leute' and 'ich sag mal' are casual speech."},
      {q:"How punctual should you be for a job interview in Germany?",opts:["On time or a few minutes early","About 15 minutes late is fine","Arrival time doesn't matter","Exactly one hour early"],a:0,ex:"Punctuality matters a lot in Germany; arriving late to an interview makes a poor first impression."}]},
    {t:"B1 review mix",s:"Review",qs:[
      {q:"Which pair of words balances two arguments?",opts:["einerseits ... andererseits","sowohl ... nachdem","weder ... damit","nicht nur ... obwohl"],a:0,ex:"'einerseits ... andererseits' (on the one hand ... on the other) presents both sides of an issue."},
      {q:"Review: complete 'Ich finde, dass Bewerbungen online einfacher ___.'",opts:["sind","seid","ist","sein"],a:0,ex:"In the dass-clause the verb goes last and agrees with the plural subject 'Bewerbungen'."},
      {q:"Review: complete 'Du ___ dich bei dieser Firma bewerben – sie ist super!'",opts:["solltest","sollen","solle","gesollt"],a:0,ex:"Advice to 'du' uses the Konjunktiv II form 'solltest' + infinitive at the end."}]},
    {t:"Challenge: essays and interviews",s:"Challenge",qs:[
      {q:"Choose the best-formed conclusion sentence.",opts:["Zusammenfassend lässt sich sagen, dass Homeoffice Vor- und Nachteile hat.","Zusammenfassend lässt sich sagen, dass Homeoffice hat Vor- und Nachteile.","Zusammenfassend sich lässt sagen, dass Homeoffice Vor- und Nachteile hat.","Zusammenfassend lässt sagen sich, dass Homeoffice Vor- und Nachteile hat."],a:0,ex:"'lässt' is in position 2, 'sich' follows the verb, and in the dass-clause 'hat' goes last."},
      {q:"Complete: 'Ich habe mich ___ die Stelle beworben, ___ ich Erfahrung im Marketing habe.'",opts:["um / weil","für / dass","auf / ob","um / denn"],a:0,ex:"'sich bewerben um' is the standard phrase, and verb-final 'habe' needs 'weil', not 'denn'."},
      {q:"Which sentence correctly combines advice and a reason?",opts:["Sie sollten Ihre Stärken nennen, weil das überzeugend wirkt.","Sie sollten Ihre Stärken nennen, weil das wirkt überzeugend.","Sie sollten nennen Ihre Stärken, weil das überzeugend wirkt.","Sie sollten Ihre Stärken nennen, weil wirkt das überzeugend."],a:0,ex:"The infinitive 'nennen' closes the main clause, and 'wirkt' goes to the end of the weil-clause."}]}
  ],
  // Module 6: Relative Clauses & Describing People
  [
    {t:"Character words",s:"Vocabulary",qs:[
      {q:"What does 'zuverlässig' mean?",opts:["reliable","helpful","curious","lazy"],a:0,ex:"'sich verlassen auf' means to rely on, so a 'zuverlässig' person is reliable."},
      {q:"What does 'hilfsbereit' mean?",opts:["helpful","reliable","shy","strict"],a:0,ex:"'die Hilfe' (help) + 'bereit' (ready): someone who is ready to help."},
      {q:"'Er sieht müde aus' means …",opts:["He looks tired.","He feels tired.","He sees a tired man.","He seems to sleep."],a:0,ex:"'aussehen' + adjective describes appearance: 'Er sieht müde aus' = he looks tired."}]},
    {t:"Hair, build and opposites",s:"Vocabulary",qs:[
      {q:"What are 'lockige Haare'?",opts:["curly hair","straight hair","short hair","grey hair"],a:0,ex:"'die Locke' is a curl, so 'lockige Haare' are curly; straight hair is 'glatte Haare'."},
      {q:"Which adjective contrasts with 'schlank' when describing build?",opts:["kräftig","glatt","höflich","lockig"],a:0,ex:"'schlank' means slim and 'kräftig' means sturdy or strongly built."},
      {q:"Which adjective is the opposite of 'zuverlässig'?",opts:["unzuverlässig","unglücklich","ungeduldig","unfreundlich"],a:0,ex:"The prefix un- makes an adjective negative: zuverlässig (reliable) → unzuverlässig (unreliable)."}]},
    {t:"Sounds in describing words",s:"Pronunciation",qs:[
      {q:"Listen. How is the 'v' in 'zuverlässig' pronounced?",say:"zuverlässig",opts:["like 'f'","like English 'v'","like 'w'","it is silent"],a:0,ex:"In native German words 'v' is usually pronounced 'f', as in 'Vater', 'viel' and 'zuverlässig'."},
      {q:"Listen. Which part of 'hilfsbereit' is stressed?",say:"hilfsbereit",opts:["the first: hilfs-","the second: -be-","the last: -reit","all parts equally"],a:0,ex:"In compound adjectives the first part usually carries the main stress: HILFSbereit."},
      {q:"Listen. What kind of 'a' do you hear in 'glatte'?",say:"glatte Haare",opts:["a short 'a'","a long 'a'","an 'ä' sound","an 'o' sound"],a:0,ex:"A vowel followed by a double consonant, like the 'tt' in 'glatt', is short."}]},
    {t:"der, die, das: who and that",s:"Grammar",qs:[
      {q:"Complete: 'Das ist der Mann, ___ neben mir wohnt.'",opts:["der","den","dem","die"],a:0,ex:"'Mann' is masculine and is the subject of 'wohnt', so the relative pronoun is nominative 'der'."},
      {q:"Complete: 'Ich habe eine Kollegin, ___ sehr hilfsbereit ist.'",opts:["die","der","das","den"],a:0,ex:"'Kollegin' is feminine and the subject of 'ist', so the pronoun is nominative feminine 'die'."},
      {q:"Complete: 'Das Kind, ___ dort spielt, ist mein Neffe.'",opts:["das","der","dem","den"],a:0,ex:"The pronoun agrees with 'das Kind' (neuter), even though the child is a boy."}]},
    {t:"Relative pronouns: cases",s:"Grammar",qs:[
      {q:"Complete: 'Die Frau, ___ ich gestern getroffen habe, ist Ärztin.'",opts:["die","der","den","dem"],a:0,ex:"'die Frau' is the object of 'getroffen', and feminine accusative is 'die'."},
      {q:"Complete: 'Das sind die Kollegen, mit ___ ich arbeite.'",opts:["denen","den","die","dem"],a:0,ex:"'mit' takes the dative, and the dative plural relative pronoun is 'denen'."},
      {q:"Complete: 'Der Film, ___ wir gesehen haben, war spannend.'",opts:["den","der","dem","das"],a:0,ex:"'der Film' is the object of 'gesehen', so masculine accusative 'den' is needed."}]},
    {t:"Reading: portraits",s:"Reading",qs:[
      {q:"Read: 'Mein Bruder ist groß und schlank und hat lockige Haare. Er ist sehr hilfsbereit, aber manchmal unpünktlich.' Which is true?",opts:["He is helpful but sometimes late.","He is short with straight hair.","He is always on time.","He is sturdy and unfriendly."],a:0,ex:"'hilfsbereit' means helpful and 'manchmal unpünktlich' means sometimes not on time."},
      {q:"Read: 'Frau Berg ist die Nachbarin, der ich meinen Schlüssel gebe, wenn ich verreise.' What does the writer do?",opts:["Gives Frau Berg the key when away","Takes Frau Berg's key on trips","Travels together with Frau Berg","Loses the key when travelling"],a:0,ex:"'der' is dative here: the writer gives the key to Frau Berg when going away (verreisen)."},
      {q:"Read: 'Gesucht: Babysitter, der zuverlässig ist und Kinder mag. Erfahrung ist ein Plus.' What is required?",opts:["Being reliable and liking kids","Several years of experience","A driving licence and a car","Good cooking and baking skills"],a:0,ex:"The relative clause lists the requirements; experience is only 'ein Plus' (a bonus)."}]},
    {t:"Listening: who is who?",s:"Listening",qs:[
      {q:"Listen. Who is the speaker talking about?",say:"Das ist die Lehrerin, die mir am meisten geholfen hat.",opts:["The teacher who helped most","The doctor who helped most","The teacher she disliked","The neighbour who moved"],a:0,ex:"'die Lehrerin' is the teacher, and the relative clause says she helped the speaker most."},
      {q:"Listen. What does the man look like?",say:"Der Mann mit den glatten Haaren sieht sehr freundlich aus.",opts:["Straight hair, looks friendly","Curly hair, looks friendly","Straight hair, looks angry","Bald, looks very tired"],a:0,ex:"'glatte Haare' means straight hair and 'sieht freundlich aus' means looks friendly."},
      {q:"Listen. What is said about the friends?",say:"Das sind die Freunde, mit denen ich nach Italien fahre.",opts:["Going to Italy with them","They live in Italy now","They are Italian people","They came back from Italy"],a:0,ex:"'mit denen ich nach Italien fahre' means the speaker is travelling to Italy with them."}]},
    {t:"Pointing people out",s:"Speaking",qs:[
      {q:"You want to point out a person at a party. What do you say?",opts:["Siehst du die Frau, die dort tanzt?","Siehst du die Frau, der dort tanzt?","Siehst du die Frau, die tanzt dort?","Siehst du die Frau, dort die tanzt?"],a:0,ex:"The pronoun matches 'die Frau' (nominative), and the verb 'tanzt' goes to the end."},
      {q:"A friend asks: 'Wie ist dein neuer Chef?' Which answer is correct?",opts:["Er ist sehr zuverlässig und hilfsbereit.","Er ist sehr zuverlässiger und hilfsbereiter.","Er sieht sehr zuverlässig an.","Er hat sehr zuverlässig und hilfsbereit."],a:0,ex:"After 'sein' adjectives take no ending; 'aussehen' needs 'aus', not 'an'."},
      {q:"Someone asks: 'Wer ist das auf dem Foto?' Which answer is correct?",opts:["Das ist der Freund, dem ich oft helfe.","Das ist der Freund, den ich oft helfe.","Das ist der Freund, der ich oft helfe.","Das ist der Freund, denen ich oft helfe."],a:0,ex:"'helfen' takes the dative, so the masculine relative pronoun is 'dem'."}]},
    {t:"Writing a portrait",s:"Writing",qs:[
      {q:"Choose the correctly written sentence about your father.",opts:["Der Mann, der dort steht, ist mein Vater.","Der Mann der dort steht, ist mein Vater.","Der Mann, der steht dort, ist mein Vater.","Der Mann, den dort steht, ist mein Vater."],a:0,ex:"A relative clause is enclosed by commas, has its verb last, and here needs nominative 'der'."},
      {q:"Fill the gap: 'Ich kenne den ___ Mann von nebenan.'",opts:["netten","nette","netter","nettes"],a:0,ex:"After 'den' (masculine accusative) the adjective ending is -en: 'den netten Mann'."},
      {q:"Fill the gap: 'Der ___ Kollege heißt Jonas.'",opts:["neue","neuen","neuer","neues"],a:0,ex:"After 'der' in the nominative singular the adjective ending is -e: 'der neue Kollege'."}]},
    {t:"Describing people politely",s:"Culture",qs:[
      {q:"Which comment about someone's appearance is generally considered impolite?",opts:["Du bist aber dick geworden!","Die Brille steht dir gut.","Du siehst erholt aus.","Schöne Haare hast du!"],a:0,ex:"Comments on weight are seen as rude in Germany; compliments on glasses, hair or looking rested are fine."},
      {q:"Which quality is often named as a key value in German working life?",opts:["Zuverlässigkeit (reliability)","Unpünktlichkeit (lateness)","Lautstärke (loudness)","Faulheit (laziness)"],a:0,ex:"Being reliable and keeping promises and deadlines is highly valued in German workplaces."},
      {q:"In a German job reference, what does 'stets zu unserer vollsten Zufriedenheit' signal?",opts:["Very good performance","Poor performance","Average performance","The person was fired"],a:0,ex:"Arbeitszeugnisse use coded phrases; 'stets' + 'vollsten Zufriedenheit' is the top grade."}]},
    {t:"Describing people recap",s:"Review",qs:[
      {q:"Which relative pronoun is dative plural?",opts:["denen","den","die","dem"],a:0,ex:"The dative plural relative pronoun is 'denen', which differs from the article 'den'."},
      {q:"Complete: 'Wie sieht deine Schwester ___?'",opts:["aus","an","ab","auf"],a:0,ex:"'aussehen' (to look like) is separable, so 'aus' goes to the end of the question."},
      {q:"Complete: 'Ich danke der ___ Nachbarin.'",opts:["netten","nette","netter","nettem"],a:0,ex:"'danken' takes the dative; after 'der' in the dative the adjective ending is -en."}]},
    {t:"Challenge: relative clauses",s:"Challenge",qs:[
      {q:"Complete: 'Das ist die Stadt, in ___ ich geboren bin.'",opts:["der","die","dem","denen"],a:0,ex:"'in' for a location takes the dative, and the feminine dative relative pronoun is 'der'."},
      {q:"Which sentence has the correct adjective ending and relative pronoun?",opts:["Wir sprechen mit dem netten Mann, der hier wohnt.","Wir sprechen mit dem nette Mann, der hier wohnt.","Wir sprechen mit den netten Mann, der hier wohnt.","Wir sprechen mit dem netten Mann, den hier wohnt."],a:0,ex:"'mit' needs dative 'dem netten', and the man is the subject of 'wohnt', so nominative 'der'."},
      {q:"Complete: 'Die Leute, ___ ich die Stadt gezeigt habe, kamen aus Kanada.'",opts:["denen","die","den","deren"],a:0,ex:"'jemandem etwas zeigen': 'die Stadt' is the accusative, so the people need dative plural 'denen'."}]}
  ]
];
